def refusal_rows():
    """قائمة (سؤال، إجابة) بعد توسيع الصياغات الثانية."""
    out = []
    for q, a, alts in REF:
        out.append((q, a))
        for q2 in (alts or []):
            out.append((q2, a))
    return out
